function inCombat(){return !!engine&&(engine.s.horde.phase==='active'||engine.enemies.some(z=>!z.dead&&!z.lying&&Math.hypot(z.x-engine.s.player.x,z.y-engine.s.player.y)<190));}
function paintNotices(){const combat=inCombat(),items=notices.visible(Date.now(),combat),html=items.map(n=>`<div class="toast ${n.tone}" title="${esc(n.text)}">${esc(n.text)}${n.count>1?' ×'+n.count:''}</div>`).join(''),key=(menu?'menu':'world')+html;if(key===noticeMarkup)return;noticeMarkup=key;$('#toasts').innerHTML=menu?'':html;$('#menu-toasts').innerHTML=menu?html:'';}
function toast(text,tone='normal'){if(started){if(tone==='warn'&&menu)audio.ui('deny');else if(tone==='gold'&&!inCombat())audio.ui('gold');}if(engine){const s=engine.s;toastLog.unshift({text:String(text),tone,time:'第'+s.day+'天 '+String(Math.floor(s.minute/60)).padStart(2,'0')+':'+String(Math.floor(s.minute%60)).padStart(2,'0')});toastLog.length=Math.min(toastLog.length,60);}notices.push(text,tone,Date.now(),inCombat()&&!menu);paintNotices();}
function touchTarget(){const e=engine,p=e.s.player;if(e.buildMode)return {x:p.x+Math.cos(p.facing)*80,y:p.y+Math.sin(p.facing)*80};if(e.weaponStats(e.currentItem())){const near=e.enemies.filter(z=>!z.dead&&!z.lying).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(near&&Math.hypot(near.x-p.x,near.y-p.y)<300)return {x:near.x,y:near.y-20};}return e.nearestPlot(p,80)||{x:p.x+Math.cos(p.facing)*120,y:p.y+Math.sin(p.facing)*120};}

