function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>32*1024*1024){toast('存档文件超过32MB，请选择单份家园存档。','warn');return;}try{const raw=JSON.parse(await file.text());if(raw.format==='ember-farm-recovery'){showMenu('restoreArchive',{files:raw.files});return;}if(raw.format==='ember-farm-checkpoint'){showMenu('restoreArchive',{files:{main:raw.main,backup:raw.backup}});return;}const state=Engine.parse(JSON.stringify(raw));if(isStandalone(state)){toast('这份文件属于旧版独立存档，当前家园未更改。请保留原文件作为备份。','warn');return;}showMenu('confirmImport',{state});}catch(e){toast(e.message||'无法读取存档。','warn');}};input.click();}
