document.addEventListener('click',e=>{if(!engine)return;unlockAudio();const button=e.target.closest('button');if(!button)return;if(button.dataset.radial!=null&&radial){radial.sel=Number(button.dataset.radial);closeRadial(true);return;}if(button.dataset.action)handleAction(button,e);else if(button.dataset.menu){if(started&&menu==='outpost'){const lock=menuLock(engine,outpostUI);if(lock==='render'){renderMenu();save();return;}if(lock){toast(lock);return;}}showMenu(button.dataset.menu);}else if(button.dataset.slot!=null&&!engine.paused)selectSlot(Number(button.dataset.slot),true);else if(button.dataset.quest){engine.claimQuest(button.dataset.quest);save();updateHUD();}else if(button.id==='defend-now'){engine.beginHorde();save();}else if(button.id==='touch-use'&&!engine.paused&&e.detail===0){engine.use(touchTarget());}else if(button.id==='touch-interact'&&!engine.paused)engine.interact();});
document.addEventListener('input',e=>{if(!engine)return;if(e.target.id==='recipe-search'){const value=e.target.value.trim();document.querySelectorAll('[data-recipe-name]').forEach(card=>card.hidden=!card.dataset.recipeName.includes(value));}else if(e.target.id==='volume'){engine.s.settings.sound=Number(e.target.value);persistPreferences();}else if(['vol-music','vol-ambience','vol-sfx'].includes(e.target.id)){audioPrefs[e.target.id.slice(4)]=Math.max(0,Math.min(1,Number(e.target.value)||0));persistPreferences();}else if(e.target.matches('.qty-input')){const row=e.target.closest('.trade-item'),direction=menuTab==='sell'?'sell':'buy',n=Math.max(1,Math.floor(Number(e.target.value)||1)),price=Number(e.target.dataset.price);row.querySelector('.trade-total').textContent=`总额 ${n*price} · 交易后 ${engine.s.money+(direction==='buy'?-n*price:n*price)}`;}});
document.addEventListener('change',e=>{if(!engine)return;if(e.target.id==='atlas-region'){atlasUI.selected=e.target.value;atlasUI.tab='world';renderMenu();return;}if(e.target.id==='lesson-region'){journalUI.filter=e.target.value;renderMenu();return;}if(e.target.id==='d-batch'){districtUI.batch=Number(e.target.value);renderMenu();return;}if(e.target.id==='r-exchange-seed'){rebuildUI.seedChoice=e.target.value;renderMenu();return;}if(e.target.id==='r-farm-plan'){engine.setFarmPlan(e.target.value);renderMenu();save();return;}if(e.target.matches('[data-f-module-slot]')){if(!engine.equipModule(e.target.dataset.weapon,e.target.dataset.fModuleSlot,e.target.value))toast('需要随身拥有组件和这把枪，且组件未被占用。');renderMenu();save();return;}const frontierFields={'f-preview-crop':'previewCrop','f-eco-tool':'ecoTool','f-kit-item':'kitId','f-weapon':'weapon','f-sample':'sampleId'};if(frontierFields[e.target.id]){frontierUI[frontierFields[e.target.id]]=e.target.id==='f-sample'?Number(e.target.value):e.target.value;renderMenu();return;}if(e.target.matches('[data-priority-resident]')){engine.setPriority(e.target.dataset.priorityResident,e.target.dataset.role,Number(e.target.value));renderMenu();save();return;}if(e.target.matches('[data-stall-price]')){engine.setStallPrice(e.target.dataset.stallPrice,e.target.value);renderMenu();save();return;}if(e.target.matches('[data-resident]')){engine.setRole(e.target.dataset.resident,e.target.value);renderMenu();save();return;}if(e.target.id==='zoom'){engine.s.settings.zoom=Number(e.target.value);persistPreferences();}if(e.target.id==='ui-scale'){engine.s.settings.uiScale=Number(e.target.value);applyUIScale();persistPreferences();}});
document.addEventListener('keydown',e=>{if(!engine)return;unlockAudio();if(keyCaptureActive()){e.preventDefault();keys.clear();const msg=captureKey(engine.s.settings,e.key.toLowerCase());if(msg)toast(msg);persistPreferences();renderMenu();return;}const key=mapKey(engine.s.settings,e.key.toLowerCase());if(key==='tab'&&menu){const focusable=[...$('#modal').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],summary')].filter(el=>!el.hidden&&(!el.getClientRects||el.getClientRects().length>0));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if(!started){if(key==='escape'&&menu!=='welcome'){e.preventDefault();closeMenu();}return;}const typing=e.target.matches('input,select,textarea');if(typing&&e.key!=='Escape')return;if(['tab',' ','arrowup','arrowdown','arrowleft','arrowright','escape'].includes(key))e.preventDefault();if(radial){if(key==='escape')closeRadial(false);else if(/^[1-9]$/.test(key)&&Number(key)<=radial.items.length){radial.sel=Number(key)-1;paintRadial();}return;}if(key==='escape'){if(engine.buildMode){engine.buildMode=null;return;}if(menu)closeMenu();else showMenu('pause');return;}if(menu==='outpost'){const mk=menuKey(engine,outpostUI,key);if(mk){e.preventDefault();if(mk==='render'){renderMenu();if(['done','caught'].includes(engine.steal?.phase))save();}return;}}if(key==='tab'){if(!e.repeat&&!menu&&!tabHeld){tabHeld=true;tabTimer=setTimeout(()=>{tabTimer=null;if(tabHeld)openRadial();},300);}return;}if(menu&&/^[1-9]$/.test(key)){const pick=document.querySelector('#modal [data-hotkey="'+key+'"]');if(pick&&!pick.disabled){e.preventDefault();handleAction(pick,e);}return;}if(engine.paused)return;keys.add(key);if(e.repeat)return;if(key===' '){engine.spaceTip?.();engine.dodge?.(moveVector());return;}if(key==='e')engine.interact();else if(key==='x')engine.shove?.();else if(key==='r')engine.reloadWeapon();else if(key==='q'&&engine.buildMode)engine.rotation=(engine.rotation+1)%4;else if(key==='v')engine.toggleCrouch();else if(key==='g')engine.throwStone(renderer.worldPoint(mouse.x,mouse.y));else if(key==='h')capturePhoto();else if(key==='t')engine.cycleAim();else if(key==='z')toggleDefense();else if(key==='l')showMenu('outpost',{view:'log'});else if(key==='f'){if(engine.f?.route)showMenu('frontier',{tab:'expedition'});}else if(['c','b','m','j','k'].includes(key))showMenu({c:'craft',b:'build',m:'map',j:'quests',k:'skills'}[key]);else if(/^[0-9]$/.test(key))selectSlot(key==='0'?9:Number(key)-1,true);});
document.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(engine)keys.delete(mapKey(engine.s.settings,e.key.toLowerCase()));if(e.key==='Tab'){const held=tabHeld;tabHeld=false;if(tabTimer){clearTimeout(tabTimer);tabTimer=null;}if(radial)closeRadial(true);else if(held&&started&&!menu&&engine)showMenu('inventory');}});
// v0.23：按住 Tab 的轮盘（制作、建造、地图……），松开打开选中的那一格；轻按 Tab 还是背包
function moveVector(){const x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;return x||y?{x,y}:null;}
function openRadial(){if(!started||menu||!engine||radial)return;const items=radialItems(engine),r=$('#world-viewport')?.getBoundingClientRect?.();let pos=null,cx=0,cy=0;if(r&&r.width>0&&r.height>0){const inside=lastPtr&&lastPtr.x>=r.left&&lastPtr.x<=r.left+r.width&&lastPtr.y>=r.top&&lastPtr.y<=r.top+r.height,keep=(v,lo,hi)=>lo>hi?(lo+hi)/2:Math.max(lo,Math.min(hi,v)),m=170;pos={x:Math.round(keep(inside?lastPtr.x-r.left:r.width/2,m,r.width-m)),y:Math.round(keep(inside?lastPtr.y-r.top:r.height/2,m,r.height-m))};cx=r.left+pos.x;cy=r.top+pos.y;}radial={items,sel:-1,wasPaused:engine.paused,pos,cx,cy};engine.paused=true;keys.clear();mouse.held=false;const el=$('#radial');if(el){el.innerHTML=radialHtml(items,-1,pos);el.hidden=false;}document.body.classList.add('radial-open');}
function paintRadial(){const el=$('#radial');if(radial&&el)el.innerHTML=radialHtml(radial.items,radial.sel,radial.pos);}
function closeRadial(activate){if(!radial)return;const r=radial;radial=null;tabHeld=false;const el=$('#radial');if(el){el.hidden=true;el.innerHTML='';}document.body.classList.remove('radial-open');if(!menu&&engine)engine.paused=!!r.wasPaused;if(activate&&r.sel>=0)runRadial(r.items[r.sel]);}
function runRadial(it){if(!it||!engine)return;const id=it.id;if(id==='craft')showMenu('craft');else if(id==='build')showMenu('build');else if(id==='map')showMenu('map');else if(id==='journal')showMenu('quests');else if(id==='skills')showMenu('skills');else if(id==='log')showMenu('outpost',{view:'log'});else if(id==='defense')toggleDefense();else if(id==='photo')capturePhoto();else if(id==='aim')engine.cycleAim?.();else if(id==='route'){if(engine.f?.route)showMenu('frontier',{tab:'expedition'});}}
document.addEventListener('pointermove',e=>{lastPtr={x:e.clientX,y:e.clientY};if(!radial)return;const on=e.target?.closest?.('[data-radial]'),sel=on?Number(on.dataset.radial):radialPick(radial.items.length,e.clientX-radial.cx,e.clientY-radial.cy);if(sel!==radial.sel){radial.sel=sel;paintRadial();}});
