$('#world').addEventListener('pointerdown',e=>{unlockAudio();if(!engine||engine.paused||e.button!==0)return;const r=$('#world').getBoundingClientRect();Object.assign(mouse,canvasPoint(e.clientX,e.clientY,r,renderer.w,renderer.h));mouse.held=true;engine.use(renderer.worldPoint(mouse.x,mouse.y));toolTimer=.22;$('#world').focus();});
document.addEventListener('pointerup',()=>{mouse.held=false;touchHeld=false;touchReel=false;});document.addEventListener('pointercancel',()=>{mouse.held=false;touchHeld=false;touchReel=false;clearJoy();});$('#touch-interact').addEventListener('pointerdown',()=>{touchReel=true;});
