function toggleDefense(){if(!renderer)return;renderer.defense=!renderer.defense;if(engine)toast(renderer.defense?'防线视图：绿圈是有人驻守的射程，红框是薄弱的围栏。再按 Z 关闭。':'已关闭防线视图。');}
